/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

public METInventLocationIdTO populateInventLocationTemp(METInventLocationIdTO tempBuffer)
{
    Unchecked(Uncheck::XDS)
    {
        InventLocation inventLocation;

        while select InventLocationId, Name, InventSiteId
            from inventLocation
        {
            tempBuffer.clear();
            tempBuffer.InventLocationId = inventLocation.InventLocationId;
            tempBuffer.Name             = inventLocation.Name;
            tempBuffer.InventSiteId     = inventLocation.InventSiteId;

            tempBuffer.insert();
        }

    }

    return tempBuffer;
}
